// Verify the HMAC signature before anything downstream touches the payload.
//
// The webhook URL is effectively public, so a request that arrives here has
// proved nothing yet. Signature material is `timestamp.rawBody`, which is why
// "Raw Body" is enabled on the webhook node: re-serialising the parsed object
// would change key order or spacing and every signature would fail.
//
// This mirrors WebhookDispatcher::verify() in the PHP backend. The two are
// kept in step by n8n/test/signature.test.mjs, which runs this exact code
// against signatures produced by the PHP implementation.

const crypto = require('crypto');

const TOLERANCE_SECONDS = 300;

// Where the secret lives depends on how this n8n is hosted, and a workflow
// that only knows one of the two breaks silently on the other:
//
//   self-hosted  $env, set in n8n/.env and passed through docker-compose.yml
//   n8n Cloud    $vars, set under Settings -> Variables ($env is blocked and
//                cannot be unblocked, because you do not own the environment)
//
// Both lookups throw rather than return undefined when unavailable, so each
// one is guarded and whichever answers first wins.
function readSecret() {
  try {
    if (typeof $vars !== 'undefined' && $vars.CONSERJE_WEBHOOK_SECRET) {
      return $vars.CONSERJE_WEBHOOK_SECRET;
    }
  } catch (e) {
    // $vars is not available on this instance; fall through to $env.
  }

  try {
    return $env.CONSERJE_WEBHOOK_SECRET;
  } catch (e) {
    return undefined;
  }
}

const secret = readSecret();

if (!secret) {
  throw new Error(
    'CONSERJE_WEBHOOK_SECRET is not readable on this n8n instance. ' +
    'Self-hosted: set it in n8n/.env and restart the container. ' +
    'n8n Cloud: add it under Settings -> Variables.'
  );
}

const item = $input.first();
const headers = item.json.headers || {};
const signature = headers['x-conserje-signature'];
const timestamp = Number(headers['x-conserje-timestamp']);

if (!signature || !Number.isFinite(timestamp)) {
  throw new Error('Rejected: signature headers are missing.');
}

if (!item.binary || !item.binary.data) {
  throw new Error(
    'Rejected: no raw body. Enable "Raw Body" in the webhook node options.'
  );
}

const raw = Buffer.from(item.binary.data.data, 'base64').toString('utf8');

// Reject stale requests: without this, a captured payload stays replayable
// forever, because its signature never stops being correct.
const now = Math.floor(Date.now() / 1000);

if (Math.abs(now - timestamp) > TOLERANCE_SECONDS) {
  throw new Error('Rejected: timestamp outside tolerance, possible replay.');
}

const expected = crypto
  .createHmac('sha256', secret)
  .update(`${timestamp}.${raw}`)
  .digest('hex');

const expectedBuffer = Buffer.from(expected, 'utf8');
const actualBuffer = Buffer.from(String(signature), 'utf8');

// Length is checked first because timingSafeEqual throws on a mismatch.
if (
  expectedBuffer.length !== actualBuffer.length ||
  !crypto.timingSafeEqual(expectedBuffer, actualBuffer)
) {
  throw new Error('Rejected: bad signature.');
}

return [{ json: JSON.parse(raw) }];

