// Flatten the nested payload into one row per lead.
//
// The transcript is joined into a single cell rather than dropped: when a
// lead turns out to be mis-scored, the conversation is the only way to find
// out why.

const payload = $input.first().json;
const lead = payload.lead || {};
const conversation = payload.conversation || {};

const transcript = (conversation.transcript || [])
  .map((turn) => `${turn.role === 'user' ? 'Visitor' : 'Assistant'}: ${turn.text}`)
  .join('\n');

return [{
  json: {
    receivedAt: new Date(payload.timestamp * 1000).toISOString(),
    site: (payload.site || {}).id || '',
    tier: lead.tier || '',
    score: lead.score ?? '',
    name: lead.name || '',
    email: lead.email || '',
    phone: lead.phone || '',
    company: lead.company || '',
    need: lead.need || '',
    timeline: lead.timeline || '',
    budgetBand: lead.budgetBand || '',
    summary: lead.summary || '',
    turns: conversation.turns ?? '',
    conversationId: conversation.id || '',
    transcript,
    status: 'new',
  },
}]
